import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"Real driver testing — 3 execution modes SSOT (mock only / real-optional / real-required)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/real-driver-testing.md","filePath":"concepts/real-driver-testing.md"}'),d={name:"concepts/real-driver-testing.md"};function i(s,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="real-driver-testing-—-3-execution-modes-ssot-mock-only-real-optional-real-required" tabindex="-1">Real driver testing — 3 execution modes SSOT (mock only / real-optional / real-required) <a class="header-anchor" href="#real-driver-testing-—-3-execution-modes-ssot-mock-only-real-optional-real-required" aria-label="Permalink to &quot;Real driver testing — 3 execution modes SSOT (mock only / real-optional / real-required)&quot;">​</a></h1><p>kiwa&#39;s v1.21 auth milestone landed 4 protocol adapters (WebAuthn L3 + Passkey + OAuth 2.1 + OIDC) as <strong>pure mocks</strong> — 0 network, 0 container, ~1 ms per test. That is the first-line contract. v1.22 layers <strong>real drivers</strong> on top — Keycloak testcontainers (OIDC), oauth2-mock-server testcontainers (OAuth 2.1), Chrome caBLE hybrid transport (Passkey). Those are the second-line fidelity check. This concept doc is the SSOT for <strong>how the two layers coexist</strong> — the 3 execution modes each test suite exposes, when to pick each, and where the release-gate fidelity axis sits.</p><h2 id="the-3-modes" tabindex="-1">The 3 modes <a class="header-anchor" href="#the-3-modes" aria-label="Permalink to &quot;The 3 modes&quot;">​</a></h2><p>Every v1.22 test surface (<code>@kiwa-test/auth</code> v0.5, dogfood apps, tutorials 37-38) exposes three execution modes gated on the <code>KIWA_MODE</code> environment variable.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Trigger</th><th>Behaviour</th><th>Latency budget</th><th>When to use</th></tr></thead><tbody><tr><td><code>mock only</code></td><td><code>KIWA_MODE</code> unset (default)</td><td>Pure <code>@kiwa-test/auth</code> mock; every spec-critical branch runs deterministically</td><td>&lt; 5 ms per test</td><td>Every PR, every push, every local run</td></tr><tr><td><code>real-optional</code></td><td><code>KIWA_MODE=real-optional</code></td><td>Try the real driver; if the container URL / driver flag is missing, fall back to mock and print <code>warn: driver unavailable, running mock</code></td><td>&lt; 5 ms mock / &lt; 60 s real (best-effort)</td><td>Local exploratory runs where Docker may or may not be up; laptop CI where testcontainers is optional</td></tr><tr><td><code>real-required</code></td><td><code>KIWA_MODE=real</code> + protocol-specific env (<code>KEYCLOAK_URL</code> / <code>OAUTH21_BOOTSTRAP=1</code> / Chrome caBLE flag)</td><td>Fail hard if the driver is missing; run tests only against the live container / browser</td><td>&lt; 90 s per test</td><td>Nightly CI where drift detection between mock and real matters more than latency; pre-release smoke</td></tr></tbody></table><p>The <strong>default</strong> is <code>mock only</code>. That is the SSOT contract kiwa preserves — every PR runs in &lt; 5 s regardless of whether Docker is up, whether the internet is reachable, whether Chrome is installed. Any regression to that latency budget is a release-gate failure.</p><h2 id="why-3-modes-not-2" tabindex="-1">Why 3 modes (not 2) <a class="header-anchor" href="#why-3-modes-not-2" aria-label="Permalink to &quot;Why 3 modes (not 2)&quot;">​</a></h2><p>A binary &quot;mock vs real&quot; split forces every contributor to install Docker + Chrome + Keycloak just to run tests. That kills PR velocity — the mock&#39;s whole point is to keep the fast-path fast. But a pure-mock world lets the mock drift from the real thing silently.</p><p>The <code>real-optional</code> middle mode threads the needle. A contributor with Docker up gets the fidelity check for free (their local run detects drift before pushing). A contributor without Docker sees a warning but still passes the mock branch (their PR keeps flowing). CI runs <code>mock only</code> on every PR and <code>real-required</code> on nightly — the fast path stays fast, the drift catcher stays honest.</p><h2 id="the-fidelity-harness" tabindex="-1">The fidelity harness <a class="header-anchor" href="#the-fidelity-harness" aria-label="Permalink to &quot;The fidelity harness&quot;">​</a></h2><p>Every v1.22 dogfood app ships a <strong>fidelity report</strong> — a matrix of protocol behaviours checked against both the mock and the real driver. When both agree on N axes, the release-gate fidelity axis records <code>N/N</code>. When they disagree on M axes, the gate records <code>(N-M)/N</code> and flags the drift.</p><p>Concrete v1.22 axes.</p><h3 id="oidc-federation-dogfood-oidc-federation-v1-22-1" tabindex="-1">OIDC federation (dogfood-oidc-federation, v1.22-1) <a class="header-anchor" href="#oidc-federation-dogfood-oidc-federation-v1-22-1" aria-label="Permalink to &quot;OIDC federation (dogfood-oidc-federation, v1.22-1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Axis</th><th>Mock behaviour</th><th>Real Keycloak behaviour</th><th>Load-bearing?</th></tr></thead><tbody><tr><td>1 — Discovery metadata field parity</td><td>Every field in <code>.well-known/openid-configuration</code> (issuer / authorization_endpoint / token_endpoint / userinfo_endpoint / jwks_uri / scopes_supported / response_types_supported / …)</td><td>Same field set from Keycloak realm import</td><td>Yes — RP wire-shape depends on it</td></tr><tr><td>2 — DCR software_statement JWS verify</td><td>4 auth methods (<code>none</code> / <code>client_secret_basic</code> / <code>client_secret_post</code> / <code>private_key_jwt</code>)</td><td>Keycloak DCR endpoint accepts the same 4</td><td>Yes — RP registration must succeed on both</td></tr><tr><td>3 — JWKS rotation with <code>kid</code> rollover</td><td>Old key survives grace window; new key verifies immediately</td><td>Keycloak <code>POST /admin/realms/{realm}/keys/rotate</code> produces the same behaviour</td><td>Yes — RP token verify must survive rotation</td></tr><tr><td>4 — id_token full-claim verify</td><td><code>iss</code> / <code>aud</code> / <code>exp</code> / <code>iat</code> / <code>nonce</code> / <code>at_hash</code> / <code>c_hash</code> all guarded with per-reason strings</td><td>Keycloak-issued id_token verifies against the same guard set</td><td>Yes — replay attack surface</td></tr><tr><td>4a-4d — Federation trust chain resolution axes (inside window / past retention / multi-rotation / fresh key after rotation)</td><td>trust anchor + intermediate + statement chain verify + intermediate substitution attack detection</td><td>Keycloak Federation SPI + trust anchor rotation</td><td>Yes — real-network cache invalidation matters</td></tr></tbody></table><h3 id="oauth-2-1-dogfood-oauth21-provider-v1-22-2" tabindex="-1">OAuth 2.1 (dogfood-oauth21-provider, v1.22-2) <a class="header-anchor" href="#oauth-2-1-dogfood-oauth21-provider-v1-22-2" aria-label="Permalink to &quot;OAuth 2.1 (dogfood-oauth21-provider, v1.22-2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Axis</th><th>Mock behaviour</th><th>Real oauth2-mock-server behaviour</th></tr></thead><tbody><tr><td>1 — Discovery <code>/.well-known/oauth-authorization-server</code> field parity</td><td>Full field set</td><td>oauth2-mock-server exposes matching fields</td></tr><tr><td>2 — /authorize post-adapter error redirect (RFC 6749 §4.1.2.1)</td><td>Redirects with <code>error=access_denied</code> + <code>state</code> preserved</td><td>oauth2-mock-server matches (v1.21-3a review found a mock drift; v1.22-2 fixed it)</td></tr><tr><td>3 — PKCE S256 verify + <code>plain</code> refuse</td><td>Mandatory S256; <code>plain</code> throws</td><td>oauth2-mock-server refuses <code>plain</code> too</td></tr><tr><td>4 — DPoP proof htu/htm/jti/iat guard</td><td>60s clock skew, replay-detect via jti</td><td>oauth2-mock-server matches</td></tr><tr><td>5 — Refresh rotation with reuse detection</td><td>Old refresh dies; reuse revokes chain</td><td>oauth2-mock-server matches</td></tr></tbody></table><h3 id="passkey-cable-dogfood-webauthn-passkey-app-v1-22-4" tabindex="-1">Passkey caBLE (dogfood-webauthn-passkey-app, v1.22-4) <a class="header-anchor" href="#passkey-cable-dogfood-webauthn-passkey-app-v1-22-4" aria-label="Permalink to &quot;Passkey caBLE (dogfood-webauthn-passkey-app, v1.22-4)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Axis</th><th>Mock helper</th><th>Real Chrome caBLE behaviour</th></tr></thead><tbody><tr><td>1 — QR generation encodes publicKey + tunnelServerHint + nonce + sessionId</td><td><code>generateCaBLEQRCode({ initiatorDeviceId, responderDeviceId, credential, tunnelServerHint, nonce })</code> returns <code>CaBLEQRCodePayload</code></td><td>Chrome caBLE renders matching FIDO:/ QR content</td></tr><tr><td>2 — BLE advertisement handshake derives matching sharedSecret</td><td><code>performBLEHandshake(qr)</code> returns <code>CaBLEBLEHandshake</code> with <code>verified: true</code></td><td>Chrome caBLE BLE handshake matches</td></tr><tr><td>3 — WebSocket tunnel establishment</td><td><code>establishWebSocketTunnel(qr, handshake)</code> returns <code>CaBLEWebSocketTunnel</code> with <code>established: true</code></td><td>Chrome caBLE tunnel opens; DevTools reports</td></tr><tr><td>4 — Credential migration payload carries credentialId + encryptedPayload</td><td><code>migrateCredential(tunnel, credential)</code> returns <code>CaBLECredentialMigration</code></td><td>Chrome caBLE migration payload carries the credential</td></tr><tr><td>5 — Signature roundtrip preserves RP challenge + verifies</td><td><code>performSignatureRoundtrip(tunnel, credential, challenge)</code> returns <code>CaBLESignatureRoundtrip</code> with <code>verified: true</code></td><td>Chrome caBLE assertion echoes challenge + verifies</td></tr><tr><td>composite</td><td><code>runCaBLESession(options, challenge)</code> chains all 5 steps in one call</td><td>Chrome caBLE runs the full ceremony end-to-end</td></tr></tbody></table><h2 id="where-the-release-gate-hooks-in" tabindex="-1">Where the release gate hooks in <a class="header-anchor" href="#where-the-release-gate-hooks-in" aria-label="Permalink to &quot;Where the release gate hooks in&quot;">​</a></h2><p><code>@kiwa-test/quality-metrics</code> v0.2 exposes the fidelity axis as one of the 7 general-purpose axes (<code>coverage / test count / fidelity / perf p95 / mutation / a11y / dogfood-run</code>). The dogfood app calls <code>evaluateReleaseGate(report)</code> with the fidelity ratio. A verdict of <code>PASS</code> requires <strong>every axis of the fidelity report to record <code>N/N</code> in <code>KIWA_MODE=real</code></strong> — drift = release-gate failure.</p><p>Every v1.22 dogfood app publishes a fidelity report artefact on merge:</p><ul><li><code>examples/dogfood-oidc-federation/reports/fidelity-{iso-timestamp}.json</code></li><li><code>examples/dogfood-oauth21-provider/reports/fidelity-{iso-timestamp}.json</code></li><li><code>examples/dogfood-webauthn-passkey-app/reports/fidelity-{iso-timestamp}.json</code></li></ul><h2 id="the-4-anti-patterns" tabindex="-1">The 4 anti-patterns <a class="header-anchor" href="#the-4-anti-patterns" aria-label="Permalink to &quot;The 4 anti-patterns&quot;">​</a></h2><p>Real-driver testing has 4 common anti-patterns kiwa consciously refuses.</p><ol><li><strong>Assume the container is up.</strong> Every setup file guards on <code>resolveMode()</code> first. A test that reaches for <code>KEYCLOAK_URL</code> unconditionally breaks the mock-only fast path.</li><li><strong>Fold both modes into one code path.</strong> The fidelity harness runs mock + real in <strong>parallel</strong> and compares — not a single function that switches on env. Parallel exposes drift; conditional hides it.</li><li><strong>Skip axes silently.</strong> Every axis names its mock behaviour AND its real driver behaviour in the fidelity report. An axis that only records the mock side (because the real driver was not booted) is treated as <code>SKIP</code>, not <code>PASS</code>. <code>SKIP</code> shows up in the release gate as a warning; <code>PASS</code> requires both sides.</li><li><strong>Let real-driver timeouts leak into CI.</strong> The <code>real-required</code> mode has a <strong>90 s hard cap per test</strong>. Anything slower means the container never started, or the network is flaky. Fail fast, don&#39;t hang the release.</li></ol><h2 id="when-to-prefer-which-mode" tabindex="-1">When to prefer which mode <a class="header-anchor" href="#when-to-prefer-which-mode" aria-label="Permalink to &quot;When to prefer which mode&quot;">​</a></h2><ul><li><strong>PR review</strong> — <code>mock only</code>. Every reviewer runs <code>pnpm test</code> and gets a green in &lt; 5 s. Zero surprise.</li><li><strong>Local exploratory</strong> — <code>real-optional</code>. Contributor with Docker up gets fidelity. Contributor without still passes mock.</li><li><strong>Nightly CI</strong> — <code>real-required</code>. Nightly job boots all 3 containers + Chrome, runs every fidelity axis, publishes the report. Drift fires an alert; the fix goes into the next PR.</li><li><strong>Pre-release smoke</strong> — <code>real-required</code>. Ship gate — no drift means the release is safe.</li></ul><h2 id="where-to-look-next" tabindex="-1">Where to look next <a class="header-anchor" href="#where-to-look-next" aria-label="Permalink to &quot;Where to look next&quot;">​</a></h2><ul><li>Tutorial 37 (<code>docs/tutorials/37-real-driver-testing.md</code>) — Keycloak + oauth2-mock-server testcontainers wiring end-to-end</li><li>Tutorial 38 (<code>docs/tutorials/38-passkey-cable-flow.md</code>) — caBLE hybrid transport 5-axis harness</li><li>v1.21 SSOT concept doc (<code>docs/concepts/auth-protocol-testing.md</code>) — 4 pure-mock axes that this doc builds on</li></ul>',29)])])}const m=t(d,[["render",i]]);export{p as __pageData,m as default};
